            byte[] iconBytes = Convert.FromBase64String(encodedIcon);
            using (FileStream fs = new FileStream(tempIcon, FileMode.Create, FileAccess.Write, FileShare.Read))
            {
                fs.Write(iconBytes, 0, iconBytes.Length);
            }

            string systemPowerShell = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.System),
                @"WindowsPowerShell\v1.0\powershell.exe");
            if (!File.Exists(systemPowerShell)) systemPowerShell = "powershell.exe";

            ProcessStartInfo psi = new ProcessStartInfo();
            psi.FileName = systemPowerShell;
            psi.Arguments = "-NoLogo -NoProfile -ExecutionPolicy Bypass -STA -File \"" + tempScript + "\"";
            psi.UseShellExecute = false;
            psi.CreateNoWindow = true;
            Process.Start(psi);
