        catch (Exception ex)
        {
            MessageBox.Show("Video Preview Creator could not start.\r\n\r\n" + ex.Message,
                "Video Preview Creator - Launch Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
